const ITEM_TIPS: Record<string, string> = {"I02K": "+25 All Stats\n+15 Health per second\n|cff5ddf26Equip: Your Health Regeneration inflicts |r|cff83d5fcSpell|r|cff5ddf26 damage to your Hero instead of restoring health. Health Regeneration now only works during combat.|r", "I04F": "|cff81f3ceShop Item|r\n+13 to Primary Attribute\n+100 Mana\n+8% Critical Strike\n|cff5ddf26Equip: Your Magical Type effects benefit from Critical Strike chance and Critical Strike modifiers, allowing them to be Critical, dealing 65% more damage, but will not trigger effects that activate on Critical Strikes.|r", "I04J": "|cffff8c00Magical Caster Relic|r\n+12 Primary Attribute\n+15% Haste\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 10%.|r\n|cff5ddf26Equip: Every 3rd Magical Type spellcast fires a massive bolt of Arcane Energy at the closest non-Lesser Creature enemy, dealing damage equal to 20% of Primary Attribute for each second of the total base cooldown of the 3 spells that were cast. Spells  benefit from this effect at 10% effectiveness while having Glyph of Arc Striking. This is a Magical Type effect.|r", "I052": "|cff87ceebBinds to Player|r\n+35 Damage\n+15% Attack Speed\n+15% Critical Strike\n|cff5ddf26Equip: Critical Strike bonus damage is increased by additional 30%.|r\n|cff5ddf26Equip: Your hero deals 18% more damage to enemies below 25% of maximum health.|r", "I05W": "|cff81f3ceShop Item|r\n+15% Critical Strike\n+8 Potency\n|cff5ddf26Equip: The attacks of your hero and summons benefit from Potency at double effectiveness.|r\n|cff5ddf26Equip: Critical Strike bonus damage is increased by additional 20% for your hero and summons.|r", "I05X": "|cff81f3ceShop Item|r\n+32% Attack Speed\n+18% Haste\n+8 Potency", "I07F": "|cff81f3ceShop Item|r\n+10 to Primary Attribute\n+9 Mana per 5 seconds\n+5 Potency\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 13%.|r\n|cff5ddf26Equip: Siphons energy from the spellcasts of allied Heroes to trigger an electric discharge, dealing 10 plus additional 40% of Primary Attribute Magical Type damage to enemies within 400 range.|r", "I07O": "|cff81f3ceShop Item|r\n+15% Attack Speed\n+10% Haste\n+6 All Stats\n|cff5ddf26Use: Switches between 1 of 3 Orb Powers. (Cooldown: 5 seconds)\nFire: Attacks splash for 20 damage and additional 35% of Primary Attribute.|r\n|cffa7a7a4Frost: Attacks Chill the target, reducing its movement speed by 50% and its attack speed by 25% for 4 seconds.|r\n|cffa7a7a4Shadow: Attacks ignore 6 of the target's Armor.|r", "I082": "+8 Strength\n+8 Agility\n+20% Attack Speed\n|cff5ddf26Use: Grants you Unholy Power which increases your Attack Damage by 15 and provides 20% Lifesteal for 15 seconds. (Cooldown: 60 seconds)|r", "I09J": "+15 Strength\n+15 Intelligence\n|cff5ddf26Use: Summons a vicious Fel Stalker that has Feedback to fight by your side. Lasts 60 seconds. (Cooldown: 80 seconds).|r", "I0BB": "|cffff8c00Crit Relic|r\n+20% Attack Speed\n+10% Critical Strike\n+10 Damage\n|cff5ddf26Equip: Increases the damage dealt by your auto-attacks by 10%.|r\n|cff5ddf26Equip: Critical Strike bonus damage is increased by additional 25%.|r", "I0BR": "|cff87ceebBinds to Player|r\n+20 to Primary Attribute\n+28% Attack Speed\n+10 Mastery\n|cff5ddf26Equip: Your attacks have |r|cff33937f10%|r|cff5ddf26 chance to strike an additional time.|r\n|cff5ddf26Equip: Whenever you cast a spell, you ignite your weapon, causing your next attack to splash for amount equal to 100% of your Primary Attribute. This is a Magical Type effect.|r", "I0C2": "|cff81f3ceShop Item|r\n+15 All Stats\n+15 Mastery\n+12% Haste", "I0C9": "+5 All Stats\n+6 Mastery\n+7% Haste\n+12 Damage\n+3 Armor\n+3 Potency\n+65 Mana\n|cffeccf11\"The relics of Ahn'Quiraj are rumoured to have been touched by C'thun itself.\"|r", "I0DF": "+13 to Primary Attribute\n+13% Haste\n|cffeccf11\"Produces a quiet hum when placed on the finger.\"|r", "I0FU": "+12 to Primary Attribute\n+8% Attack Speed\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 12%.|r\n|cff5ddf26Equip: Grants you and nearby allies Brilliance Aura, which provides 4 mana per 5 seconds. Auras with the same name do not stack.|r", "I0FW": "|cff81f3ceShop Item|r\n+55 to Primary Attribute\n|cff5ddf26Equip: Increases the cooldown of all abilities by 12%. This effect stacks additively.|r", "I0GL": "+10 All Stats\n+4 Armor\n|cff5ddf26Equip: All damage dealt by your hero is increased by 25% against bosses.|r\n|cffeccf11\"The Stone of Jordan is far more valuable than its appearance would suggest. Men have given much to possess it.\"|r", "I0J2": "+6 Potency\n+10 Damage\n+18% Attack Speed\n|cff5ddf26Equip: Each attack causes 5 damage plus 1 per Hero Level twice.|r", "I0J4": "+10 All Stats\n|cff5ddf26Use: Boosts the armor of all nearby friendly units by 4 for 15 seconds. (Coolown: 60 seconds)|r\n|cff5ddf26Equip: Reduces damage taken from attacks by 16.|r", "I0JO": "|cffff8c00Magical Caster Relic|r\n+16 to Primary Attribute\n+10 Mastery\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 30%.|r\n|cff5ddf26Equip: Increases your base attack cooldown by 20%.|r", "I0NI": "|cffff8c00Battlecaster Relic|r\n+10 to Primary Attribute\n+16% Attack Speed\n+8 Mastery\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 12%.|r\n|cff5ddf26Equip: Your attacks have |r|cff33937f20%|r|cff5ddf26 chance to cause 40 damage plus 150% of Primary Attribute. After casting your \"Q\" ability the proc chance will be 100% and the damage dealt will be increased by 20%. This is a Magical Type effect.|r", "I0NT": "|cff81f3ceShop Item|r\n+15% Attack Speed\n+10% Haste\n+6 All Stats\n|cff5ddf26Use: Switches between 1 of 3 Orb Powers. (Cooldown: 5 seconds)\nFire: Attacks splash for 20 damage and additional 35% of Primary Attribute.|r\n|cffa7a7a4Frost: Attacks Chill the target, reducing its movement speed by 50% and its attack speed by 25% for 4 seconds.|r\n|cffa7a7a4Shadow: Attacks ignore 6 of the target's Armor.|r", "I0QN": "|cffff8c00Crit Relic|r\n+23 Damage\n+12% Critical Strike\n|cff5ddf26Equip: Your attacks ignore 3 of the target's Armor.|r\n|cff5ddf26Equip: Your Critical Strikes grant you 28% Attack Speed for 3 seconds.|r", "I0QT": "|cff81f3ceShop Item|r\n+14 to Primary Attribute\n+9 Damage\n+4 Armor\n|cff5ddf26Equip: Increases your Magical and Physical Type effectiveness by 13%, increased by an additional amount up to 25% based on the target's current Health.|r\n|cff5ddf26Equip: Increases the base cooldown of all abilities by 10%. This effect stacks additively.|r", "I0UA": "+25% Attack Speed\n+10% Haste\nClasses: |cff00ff96Monk|r\n|cff5ddf26Equip: Power Strike triggers Stance of the White Tiger’s empowered attack.|r", "I0UC": "+20 Damage\n+9% Critical Strike\nClasses: |cff00ff96Monk|r\n|cff5ddf26Equip: Your Critical Strikes reduce the remaining cooldown of Celestial Wrath by 0,3 seconds.|r", "fgrd": "+12 to Primary Attribute\n+8% Haste\n+6 Agility\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 30%.|r\n|cff5ddf26Equip: Reduces the effectiveness of Healing Type effects on your hero by 30%.|r", "ram1": "+20% Attack Speed\n+10 Damage\n+5% Haste\n|cff5ddf26Equip: Your attacks have |r|cff33937f6%|r|cff5ddf26 chance to stab the target with darkness, dealing Attrition damage equal to 150% of your Attack Damage. This effect is registered as a Chaos type basic attack. As such it gains all benefits of basic attacks.|r\n|cff5ddf26Equip: You take 20% more |r|cff83d5fcSpell|r|cff5ddf26 damage.|r", "tgrh": "+200 Mana\n-5 Armor\n|cff5ddf26Equip: Increases damage dealt by Magical and Physical Type effects by 20%.|r", "tmsc": "+10 All Stats\n|cff5ddf26Equip: Increases any damage dealt by 0,25% per point of your lowest Attribute.|r\n|cffeccf11\"This device predates life on Azeroth. Its purpose is incomprehensible to you, but holding it makes every cell of your body feel enhanced.\"|r", "war2": "+30 Strength\n-10 Intelligence\n|cff5ddf26Equip: Your Basic Attacks have 15% chance to Stun your opponent for 1 second.|r\n|cffeccf11\"You don't need lots of brains to hit hard.\"|r"};
